const c=$input.first().json;
if(!Array.isArray(c.companies)||!c.companies.length)return [];
if(c.companies.length>3)throw new Error('Use at most 3 companies.');
if(!c.stateId || c.stateId.includes('YOUR_'))throw new Error('Choose a stable unique state ID.');
const companies=[...new Set(c.companies.map(v=>String(v).trim()))];
if(companies.some(v=>!v||v.includes('YOUR_')))throw new Error('Replace company placeholders.');
return [{json:{companies,stateId:c.stateId}}];

const rows=$input.all().map(i=>i.json).filter(d=>d.record_type==='job' && d.status==='NEW');
if(!rows.length)return [];
const clean=v=>String(v??'').replace(/[<>&]/g,' ').replace(/[\r\n]+/g,' ');
return [{json:{text:'Newly observed jobs (first run is a baseline; bounded sample):\n'+rows.map(d=>[d.company_domain,d.title,d.location,d.apply_url].map(clean).join(' | ')).join('\n')}}];
